        v: [['dulu','antigamente'],['waktu kecil','quando pequeno'],['dulu saya tinggal','eu morava'],['dulu saya main','eu brincava'],['masa kecil','infância'],['sekarang','agora'],['sering','frequentemente'],['tumbuh besar','crescer']],
